#!/usr/bin/env node
// Generates tokens.css, tokens.ts and tailwind.css from tokens/tokens.json.
// Outputs are written to tokens/ (reference copies) and packages/ui/src/styles + src/tokens.ts (shipped).
// `--check` fails if any generated file is out of date (used in CI).
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const check = process.argv.includes("--check");
const source = JSON.parse(readFileSync(join(root, "tokens/tokens.json"), "utf8"));
const prefix = source.$meta.prefix;

/** Flatten nested groups into [path[], token] pairs. A token is any object with a `value`. */
function flatten(node, path = []) {
  const out = [];
  for (const [key, child] of Object.entries(node)) {
    if (key.startsWith("$") || child === null || typeof child !== "object") continue;
    if ("value" in child) out.push([[...path, key], child]);
    else out.push(...flatten(child, [...path, key]));
  }
  return out;
}

const tokens = flatten(source);
const varName = (path) => `--${prefix}-${path.join("-").replace(/\./g, "_")}`;
const header = "/* Generated by scripts/build-tokens.mjs from tokens/tokens.json. Do not edit by hand. */\n";

// Breakpoints cannot be used inside media queries as custom properties; they are emitted for reference only.
const css =
  header +
  ":root {\n" +
  tokens.map(([path, t]) => `  ${varName(path)}: ${t.value};${t.evidence === "proposed" ? " /* proposed */" : ""}`).join("\n") +
  "\n}\n";

// Nested TS object with both raw values and CSS variable references.
function buildTree(useVar) {
  const tree = {};
  for (const [path, t] of tokens) {
    let node = tree;
    path.slice(0, -1).forEach((p) => (node = node[p] ??= {}));
    node[path.at(-1)] = useVar ? `var(${varName(path)})` : t.value;
  }
  return tree;
}
const meta = Object.fromEntries(
  tokens.map(([path, t]) => [path.join("."), { evidence: t.evidence, ...(t.live ? { live: t.live } : {}), ...(t.description ? { description: t.description } : {}) }]),
);
const ts =
  "// Generated by scripts/build-tokens.mjs from tokens/tokens.json. Do not edit by hand.\n\n" +
  `/** Raw token values. */\nexport const tokens = ${JSON.stringify(buildTree(false), null, 2)} as const;\n\n` +
  `/** CSS custom property references, e.g. vars.color.ink === "var(--${prefix}-color-ink)". */\nexport const vars = ${JSON.stringify(buildTree(true), null, 2)} as const;\n\n` +
  `export type TokenEvidence = "observed" | "derived" | "proposed";\n` +
  `export interface TokenMeta { evidence: TokenEvidence; live?: string; description?: string }\n\n` +
  `/** Provenance for every token, keyed by dotted path. */\nexport const tokenMeta: Record<string, TokenMeta> = ${JSON.stringify(meta, null, 2)};\n\n` +
  "export type Tokens = typeof tokens;\n";

// Tailwind v4 theme mapping: recreates the production utility names (bg-surface, text-ink, rounded-md ...).
const tw = [];
for (const [path] of tokens) {
  const [group, ...rest] = path;
  const name = rest.join("-").replace(/\./g, "_");
  const map = {
    color: `--color-${name}`,
    radius: `--radius-${name}`,
    shadow: `--shadow-${name}`,
    space: null,
    breakpoint: `--breakpoint-${name}`,
  };
  if (group === "font" && rest[0] === "family") tw.push(`  --font-${rest[1]}: var(${varName(path)});`);
  else if (group === "font" && rest[0] === "size") tw.push(`  --text-${rest[1]}: var(${varName(path)});`);
  else if (group === "font" && rest[0] === "weight") tw.push(`  --font-weight-${rest[1]}: var(${varName(path)});`);
  else if (group === "font" && rest[0] === "tracking") tw.push(`  --tracking-${rest[1]}: var(${varName(path)});`);
  else if (group === "font" && rest[0] === "leading") tw.push(`  --leading-${rest[1]}: var(${varName(path)});`);
  else if (group === "breakpoint") tw.push(`  ${map.breakpoint}: ${source.breakpoint[rest[0]].value};`);
  else if (map[group]) tw.push(`  ${map[group]}: var(${varName(path)});`);
}
const tailwind =
  header +
  "/* Optional: Tailwind CSS v4 theme that maps HeiGin tokens to utilities (bg-surface, text-ink, rounded-md, shadow-popover ...).\n" +
  "   Usage: @import \"tailwindcss\"; @import \"@heigin/ui/tokens.css\"; @import \"@heigin/ui/tailwind.css\"; */\n" +
  "@theme inline {\n  --spacing: 4px;\n" +
  tw.join("\n") +
  "\n}\n";

const outputs = {
  "tokens/tokens.css": css,
  "tokens/tokens.ts": ts,
  "packages/ui/src/styles/tokens.css": css,
  "packages/ui/src/styles/tailwind.css": tailwind,
  "packages/ui/src/tokens.ts": ts,
};

let stale = [];
for (const [file, content] of Object.entries(outputs)) {
  const abs = join(root, file);
  const current = existsSync(abs) ? readFileSync(abs, "utf8").replace(/\r\n/g, "\n") : null;
  if (current === content) continue;
  if (check) stale.push(file);
  else writeFileSync(abs, content);
}
if (check && stale.length) {
  console.error(`Generated token files are out of date:\n  ${stale.join("\n  ")}\nRun: npm run tokens`);
  process.exit(1);
}
console.log(`${check ? "Checked" : "Built"} ${tokens.length} tokens -> ${Object.keys(outputs).length} files`);
